import{_ as r,C as s,o as n,c as i,a3 as t,E as o}from"./chunks/framework.CZBGEXos.js";const v=JSON.parse('{"title":"Majors overlay","description":"","frontmatter":{},"headers":[],"relativePath":"en/customize/majors.md","filePath":"en/customize/majors.md"}'),l={name:"en/customize/majors.md"};function d(h,e,c,u,m,p){const a=s("Screenshot");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="majors-overlay" tabindex="-1">Majors overlay <a class="header-anchor" href="#majors-overlay" aria-label="Permalink to &quot;Majors overlay&quot;">​</a></h1><p>The majors overlay draws three kinds of significant market activity directly on a chart, at the exact price each one printed at:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it marks</th></tr></thead><tbody><tr><td><strong>Major trades</strong></td><td>Individual trades in the top 10% by size for that symbol</td></tr><tr><td><strong>Clusters</strong></td><td>1-minute price levels that absorbed far more volume than a typical level on that coin</td></tr><tr><td><strong>Liquidations</strong></td><td>Forced position closes of $5,000 or more</td></tr></tbody></table>',3)),o(a,{src:"majors",alt:"A chart with the majors overlay: trade triangles and a cluster cell",caption:"Majors on a 1m chart — trade triangles, cluster cells and the tooltip of one major buy"}),e[1]||(e[1]=t('<p>It is a reading aid, not a scanner: it tells you <em>where</em> the size went on a chart you are already looking at.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>The overlay is per chart, not global. Each chart has a <strong>majors button</strong> in its toolbar, and the caret beside it opens the layer menu.</p><p>You can also press the overlay key — <strong><kbd>M</kbd></strong> by default — while the pointer is over a chart. The key is rebindable in the <strong>Home</strong> tab as <strong>Majors overlay key</strong>, next to the drawing-tool keys.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Where the overlay is available</th></tr></thead><tbody><tr><td><a href="/manual/en/tools/analyzer.html">Analyzer</a></td><td>Every chart panel, and fullscreen</td></tr><tr><td><a href="/manual/en/tools/knives.html">Knives</a></td><td>Fullscreen only</td></tr><tr><td><a href="/manual/en/tools/monitor.html">Monitor</a></td><td>Fullscreen only</td></tr></tbody></table><p>Knives and Monitor limit it to fullscreen deliberately — a ticker card is far too small for per-price markers to be readable.</p><div class="info custom-block"><p class="custom-block-title">Un-ticking every layer switches the overlay off</p><p>If you turn off all three layers, the overlay itself turns off rather than staying lit and drawing nothing, so the buttons always reflect what you can actually see. Turning it back on re-enables all three.</p></div><h2 id="reading-the-markers" tabindex="-1">Reading the markers <a class="header-anchor" href="#reading-the-markers" aria-label="Permalink to &quot;Reading the markers&quot;">​</a></h2><h3 id="major-trades-—-triangles" tabindex="-1">Major trades — triangles <a class="header-anchor" href="#major-trades-—-triangles" aria-label="Permalink to &quot;Major trades — triangles&quot;">​</a></h3><p>A triangle points <strong>the way the aggressor pushed</strong>: up and green for a buy, down and red for a sell. Its size scales with the trade&#39;s dollar value relative to the largest trade currently on screen, so the biggest print in view is always the biggest triangle.</p><p>Hovering one shows the side, dollar size, price, percentile, venue and time.</p><div class="info custom-block"><p class="custom-block-title">What the percentile means</p><p>Each trade carries the percentile it sat at <strong>when it printed</strong>. Thresholds are recomputed per symbol over a rolling 4-hour window, so <code>p99</code> means the trade was in the top 1% <em>at that moment</em> — not relative to today.</p></div><h3 id="clusters-—-filled-cells" tabindex="-1">Clusters — filled cells <a class="header-anchor" href="#clusters-—-filled-cells" aria-label="Permalink to &quot;Clusters — filled cells&quot;">​</a></h3><p>A cluster is a one-minute price level that held far more volume than a typical level on that coin. It is drawn as a filled cell at that price, with the volume printed inside.</p><ul><li><strong>Colour</strong> — the dominant side: green if buys outweighed sells, red otherwise.</li><li><strong>The number</strong> — that dominant side&#39;s volume, not the delta.</li><li><strong>Opacity</strong> — relative to the loudest level <em>currently visible</em>, so the scale re-normalises as you zoom instead of being flattened by one off-screen giant.</li></ul><p>Hovering shows total, buy, sell, delta, and the spot split where spot volume exists.</p><div class="warning custom-block"><p class="custom-block-title">&quot;no clusters — price too stable&quot; is not a fault</p><p>Levels are about 0.05% wide — roughly $55 on BTC. A quiet BTC minute does not travel that far, so the whole minute sits inside one level and nothing can stand out against its neighbours.</p><p>Very stable, very expensive coins can legitimately have <strong>no clusters at all</strong>. The overlay says so in its status line rather than looking broken on the most-watched symbol there is.</p></div><h3 id="liquidations-—-diamonds" tabindex="-1">Liquidations — diamonds <a class="header-anchor" href="#liquidations-—-diamonds" aria-label="Permalink to &quot;Liquidations — diamonds&quot;">​</a></h3><p>A diamond marks a forced position close, sized by notional value.</p><p><strong>The colour follows the pressure, not the word.</strong> A liquidated <em>long</em> is a forced <em>sell</em>, so it is drawn red and downward; a liquidated <em>short</em> is a forced buy, drawn green. This is the easiest thing here to read backwards, and it matches the liquidation tape in the Alerts window.</p><p>Hovering spells it out in words — <code>long closed → forced sell</code> — along with size, price, venue and time.</p><h2 id="the-status-line" tabindex="-1">The status line <a class="header-anchor" href="#the-status-line" aria-label="Permalink to &quot;The status line&quot;">​</a></h2><p>The overlay writes one line above the chart. It is deliberately honest about every limit rather than silently showing a partial picture:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAJORS · all venues · top 25 of 29k trades</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Fragment</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MAJORS · all venues</code></td><td>Markers come from every venue the feed covers — the default</td></tr><tr><td><code>MAJORS · binance+bybit</code> / <code>MAJORS · 4 of 7 venues</code></td><td>You narrowed the <a href="#venues">venues</a>: up to two are named, more are counted</td></tr><tr><td><code>clusters all venues</code></td><td>Shown while a venue filter is on — clusters are not filtered by venue</td></tr><tr><td><code>candles &lt;exchange&gt;</code></td><td>Shown when the candles are from a venue the markers can&#39;t come from</td></tr><tr><td><code>candles spot</code></td><td>Shown when you are viewing a spot chart</td></tr><tr><td><code>top N of M trades</code></td><td><strong>The window held M, only the biggest N are drawn</strong> — see <a href="#markers-drawn">Markers drawn</a></td></tr><tr><td><code>no clusters — price too stable</code></td><td>Explained above</td></tr><tr><td><code>7d max</code></td><td>The timeframe reaches further back than the server keeps</td></tr><tr><td><code>connecting…</code> / <code>auth failed</code> / <code>feed error</code> / <code>no data for this symbol</code></td><td>Connection state</td></tr></tbody></table><h3 id="where-the-markers-come-from" tabindex="-1">Where the markers come from <a class="header-anchor" href="#where-the-markers-come-from" aria-label="Permalink to &quot;Where the markers come from&quot;">​</a></h3><p>The feed covers seven venues: <strong>Binance</strong> perp and spot, <strong>Bybit</strong> perp and spot, <strong>OKX</strong>, <strong>Gate.io</strong> and <strong>Hyperliquid</strong> perps. Markers for a symbol are merged from all of them, whichever exchange the candles come from. You can narrow this with the <a href="#venues">Venues</a> setting.</p><p>If the candles come from a venue that is not among the marker venues, the status line says <code>candles &lt;exchange&gt;</code>. Sentaro never blanks the overlay silently.</p><p>History reaches back <strong>7 days</strong>. On a timeframe wide enough to outrun that, the left part of the chart simply has no markers, and the line says <code>7d max</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2>',30)),o(a,{src:"majors-settings",alt:"The Majors overlay settings in the Home tab",caption:"Home → Majors overlay"}),e[2]||(e[2]=t('<p>The filters live in the <strong>Home</strong> tab, under <strong>Majors overlay</strong>. They apply to every chart in every tool.</p><h3 id="markers-drawn" tabindex="-1">Markers drawn <a class="header-anchor" href="#markers-drawn" aria-label="Permalink to &quot;Markers drawn&quot;">​</a></h3><p>How many of the biggest to draw, <strong>per kind</strong>. Range <strong>25 to 1500</strong> in steps of 25, default 25.</p><p>This is the control for <strong>trades</strong>. A busy window holds thousands of them, so only the biggest ever reach the chart — and the status line tells you when that truncation happened.</p><p>It rarely matters for clusters and liquidations: there are usually far fewer of those than the limit, so their size thresholds below are what actually decides what you see.</p><h3 id="cluster-strength" tabindex="-1">Cluster strength <a class="header-anchor" href="#cluster-strength" aria-label="Permalink to &quot;Cluster strength&quot;">​</a></h3><p>Hides price levels holding less than this many times what a typical level on that coin holds. Range <strong>3× to 25×</strong> in 0.5 steps, default 5.5×.</p><ul><li><strong>3×</strong> is everything the server keeps — the loosest setting possible.</li><li><strong>6×</strong> shows only clearly strong levels.</li></ul><p>Raising it is the fastest way to quieten a noisy chart without losing the levels that matter.</p><h3 id="liquidation-size" tabindex="-1">Liquidation size <a class="header-anchor" href="#liquidation-size" aria-label="Permalink to &quot;Liquidation size&quot;">​</a></h3><p>Hides liquidations below this notional. Range <strong>$5,000 to $1,000,000</strong> in $5,000 steps, default $15,000.</p><p>$5,000 is the server&#39;s own floor — nothing smaller is ever stored, so the minimum setting is already &quot;everything there is&quot;.</p><h3 id="venues" tabindex="-1">Venues <a class="header-anchor" href="#venues" aria-label="Permalink to &quot;Venues&quot;">​</a></h3><p>Which venues big trades and liquidations may come from. A row of chips, one per venue, marked <code>perp</code> or <code>spot</code>. Default <strong>all</strong>.</p><p>Click a chip to switch that venue off or on. The counter shows how many are on, e.g. <code>4/7</code>. <strong>All venues</strong> resets the selection. Switching off the last venue snaps back to all of them, so the overlay never sits on with nothing to draw.</p><div class="info custom-block"><p class="custom-block-title">Clusters ignore this</p><p>A cluster merges every venue of a coin into one price level, so there is nothing per-venue left in it to filter. With a venue filter on, the status line says <code>clusters all venues</code> as a reminder.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a> — candle colours, drawing tools and the key bindings the overlay key sits beside</li><li><a href="/manual/en/tools/analyzer.html">Analyzer</a> — the tool where the overlay is available on every panel</li></ul>',18))])}const y=r(l,[["render",d]]);export{v as __pageData,y as default};
